#!/usr/bin/env python3
"""
Round 110b tiles patch (29 September 2026).

This site went over the 10 GB GitHub Pages will publish (11 GB), so it stopped
updating. The Climate TRACE archives gas by gas (carbon dioxide, methane,
nitrous oxide; 5.6 GB) move to their own repository, culprits-tiles-gases:

  gases/run.sh, gases/seed.py   new: what that repository's one workflow runs.
                                seed.py copies the archives from this
                                repository as it was at 64ba5fd, once.
  scripts/ct_gases.py           does nothing here now; it runs there.
  tiles/climate_trace_{co2,ch4,n2o}_*, tiles/climate_trace_gases*.json,
  climate_gases/                deleted here (still in 64ba5fd for the copy).

Run from the repository root.
"""
import base64, pathlib, re, shutil

FILES = {'gases/run.sh': '', 'gases/seed.py': '', 'scripts/ct_gases.py': ''}
GONE = re.compile(r"^(climate_trace_(co2|ch4|n2o)_.+|climate_trace_gases[^/]*\.json)$")

if not pathlib.Path("scripts").is_dir():
    raise SystemExit("round110b: scripts/ not found; run from the culprits-tiles-more root")
changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if p.exists() and p.read_bytes() == new:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(new)
    changed.append(path)
gone = 0
for p in sorted(pathlib.Path("tiles").glob("climate_trace_*")):
    if GONE.match(p.name):
        p.unlink()
        gone += 1
if pathlib.Path("climate_gases").is_dir():
    gone += sum(1 for _ in pathlib.Path("climate_gases").iterdir())
    shutil.rmtree("climate_gases")
print("round110b: " + (", ".join(changed) or "no files to write") + (f"; {gone} gas files deleted" if gone else "; nothing to delete (already applied)"))
